package com.geno1024.netdis.update

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class CanaryManifestTest {

    private val valid = """
        # Generated by the Build workflow.
        runNumber=42
        versionName=0.1.42.deadbeef
        sizeBytes=123456
        sha256=${"ab".repeat(32)}
        assetName=app-release.apk
        commit=deadbeefdeadbeef
    """.trimIndent()

    @Test
    fun `parses a published manifest`() {
        val info = CanaryManifest.parse(valid)
        assertEquals(
            CanaryInfo(
                runNumber = 42,
                versionName = "0.1.42.deadbeef",
                sizeBytes = 123456,
                sha256 = "ab".repeat(32),
                assetName = "app-release.apk",
            ),
            info,
        )
        assertEquals("abababab", info!!.shortSha)
    }

    @Test
    fun `tolerates comments, padding and missing optional keys`() {
        val info = CanaryManifest.parse(
            """
            ! comment
            # comment
               runNumber = 7
            sha256=${"0f".repeat(32)}
            """.trimIndent(),
        )
        assertEquals(7, info?.runNumber)
        assertEquals("canary", info?.versionName)
        assertEquals(0L, info?.sizeBytes)
        assertEquals(CanaryManifest.FALLBACK_ASSET_NAME, info?.assetName)
    }

    @Test
    fun `rejects manifests without a usable run number or digest`() {
        assertNull(CanaryManifest.parse(""))
        assertNull(CanaryManifest.parse("sha256=${"ab".repeat(32)}"))
        assertNull(CanaryManifest.parse("runNumber=1"))
        assertNull(CanaryManifest.parse("runNumber=1\nsha256=short"))
        assertNull(CanaryManifest.parse("runNumber=1\nsha256=${"zz".repeat(32)}"))
    }

    @Test
    fun `reads the run number from the installed version name`() {
        // CI builds carry the run number in both places.
        assertEquals(42, CanaryManifest.installedRunNumber("0.1.42.1.deadbeef", 42))
        // Local builds put the commit count in versionCode; the name wins.
        assertEquals(3, CanaryManifest.installedRunNumber("0.1.3.1.deadbeef", 417))
        // A name outside the stamp falls back to versionCode.
        assertEquals(417, CanaryManifest.installedRunNumber("canary", 417))
        assertEquals(417, CanaryManifest.installedRunNumber("0.1.x.1.deadbeef", 417))
    }

    @Test
    fun `builds safe download urls`() {
        assertTrue(
            CanaryManifest.apkUrl("app-release.apk")
                .endsWith("/Geno1024-AIGC/netdis-android/releases/download/canary/app-release.apk"),
        )
        // A path traversal or an unexpected extension falls back to the known name.
        assertTrue(CanaryManifest.apkUrl("../../evil.sh").endsWith("/app-release.apk"))
        assertTrue(CanaryManifest.apkUrl("other.exe").endsWith("/app-release.apk"))
        assertFalse(CanaryManifest.apkUrl("other.apk").endsWith("app-release.apk"))
    }

    @Test
    fun `renders a manifest that parses back`() {
        val info = CanaryInfo(
            runNumber = 9,
            versionName = "0.1.9.cafe",
            sizeBytes = 99,
            sha256 = "cd".repeat(32),
            assetName = "netdis.apk",
        )
        val text = CanaryManifest.render(info, "cafebabe")
        assertTrue(text.contains("commit=cafebabe"))
        assertEquals(info, CanaryManifest.parse(text))
    }

    @Test
    fun `mirrors wrap urls and resolve presets`() {
        val url = CanaryManifest.DIRECT_URL
        assertEquals(url, Mirrors.DIRECT.wrap(url))
        assertEquals("https://ghfast.top/$url", Mirrors.resolve("https://ghfast.top/").wrap(url))
        assertEquals("自定义", Mirrors.resolve("https://example.test").label)
        assertEquals("", Mirrors.resolve("").prefix)
    }
}
